import math

import bpy

"""VRM humanoid body-only target profile.

This profile maps the existing Mixamo intermediate skeleton produced by the
BVH pipeline onto a VRM 0.x humanoid armature using only body bones. Secondary
VRM bones such as hair, skirt, sleeve, hood strings, colliders, and spring-bone
chains are intentionally ignored.
"""

TARGET_VRM_BODY = 'VRM_BODY'

# Source is the stable internal Mixamo-style skeleton generated by the addon.
